create temporary table ticket_change_tests(result text) on commit drop;
do $$declare original public.pqr_tickets%rowtype;actor uuid;redigit uuid;commercial uuid;universal_id uuid;field_country text;staff uuid;t1 uuid:=gen_random_uuid();t2 uuid:=gen_random_uuid();r jsonb;n text;before_data jsonb;bad boolean;
begin begin
select * into strict original from public.pqr_tickets where deleted_at is null limit 1;
select id into strict actor from public.pqr_profiles where active and role='validador' limit 1;
select id into strict redigit from public.pqr_profiles where active and role='redigitador' order by created_at limit 1;
select id into strict staff from public.pqr_staff where active and role='redigitador' limit 1;
select id into strict commercial from public.pqr_profiles where active and role='comercial' limit 1;
select id into strict universal_id from public.pqr_profiles where active and role='universal' limit 1;
select p.field_country into strict field_country from public.pqr_profiles p where p.role='campo' and active limit 1;
insert into public.pqr_tickets select (jsonb_populate_record(null::public.pqr_tickets,to_jsonb(original)||jsonb_build_object('id',t1,'code','EDC-TEST-'||t1,'status','Pendiente de Redigitación','data',original.data||jsonb_build_object('id',t1,'code','EDC-TEST-'||t1,'requestType','EDC','status','Pendiente de Redigitación','auditOriginal','123456','country',field_country)))).*;
insert into public.pqr_tickets select (jsonb_populate_record(null::public.pqr_tickets,to_jsonb(original)||jsonb_build_object('id',t2,'code','RDG-TEST-'||t2,'status','Pendiente de Redigitación','data',original.data||jsonb_build_object('id',t2,'code','RDG-TEST-'||t2,'requestType','RDG','status','Pendiente de Redigitación','auditOriginal','123456','country',field_country)))).*;
perform set_config('request.jwt.claim.sub',commercial::text,true);
bad:=false;begin perform public.pqr_reclassify(t1,'{}');exception when insufficient_privilege then bad:=true;end;if not bad then raise exception 'Comercial reclasifico';end if;
perform set_config('request.jwt.claim.sub',actor::text,true);
r:=public.pqr_reclassify(t1,jsonb_build_object('requestType','RDG','redigitType','Campo','reason','Prueba: era redigitacion y no edicion'));
if r->>'requestType'<>'RDG' or nullif(r->>'fieldAccountId','') is null then raise exception 'Envio a Campo incorrecto';end if;
perform set_config('request.jwt.claim.sub',universal_id::text,true);perform set_config('request.headers','{"x-pqr-profile":"validador"}',true);
r:=public.pqr_reclassify(t1,jsonb_build_object('requestType','RDG','redigitType','Validación','personId',staff,'reason','Prueba destino Validacion'));
if r->>'redigitType'<>'Validación' or nullif(r->>'fieldAccountId','') is not null then raise exception 'Cambio de destino incorrecto';end if;
perform set_config('request.jwt.claim.sub',redigit::text,true);perform set_config('request.headers','{}',true);
r:=public.pqr_redigit_assign_batch(array[t1,t2],jsonb_build_object('redigitType','Validación','personId',staff));
if (r->>'assigned')::integer<>2 then raise exception 'Lote no asignado';end if;
select data into before_data from public.pqr_tickets where id=t1;
update public.pqr_tickets set status='Cerrado' where id=t2;
bad:=false;begin perform public.pqr_redigit_assign_batch(array[t1,t2],jsonb_build_object('redigitType','Campo'));exception when others then bad:=true;end;
if not bad or (select data from public.pqr_tickets where id=t1) is distinct from before_data then raise exception 'Lote no atomico';end if;
perform set_config('request.jwt.claim.sub',actor::text,true);
r:=public.pqr_reclassify(t1,jsonb_build_object('requestType','EDC','redigitType','Validación','personId',staff,'reason','Prueba de reclasificacion inversa'));
perform set_config('request.jwt.claim.sub',redigit::text,true);
r:=public.pqr_complete_edit(t1,true,'Prueba de cierre tras reclasificacion');
if r->>'status'<>'Cerrado' then raise exception 'No cierra edicion corregida';end if;
raise exception using errcode='P0002',message='TEST_OK';
exception when no_data_found then if sqlerrm<>'TEST_OK' then raise;end if;end;
insert into ticket_change_tests values('OK: Comercial bloqueado; PQR y Universal reclasifican; Campo y Validacion; radicado conservado; lote atomico; edicion reclasificada cierra; pruebas revertidas.');
end;$$;select * from ticket_change_tests;
